'use strict';
(()=>{
 const COOLDOWN=3*60*60*1000;
 function cooldown(h,now=Date.now()){const deadline=h.dungeonNextFightAt??0;if(!Number.isSafeInteger(deadline)||deadline<0)throw Error('Nieprawidłowy czas odnowienia lochów.');const remaining=window.BrandCombat.isNecromancer(h)?0:Math.max(0,deadline-now),seconds=Math.ceil(remaining/1000);return {remaining,deadline,text:[Math.floor(seconds/3600),Math.floor(seconds/60)%60,seconds%60].map(n=>String(n).padStart(2,'0')).join(':')};}
 const BOSSES=[
 {id:'grave-wraith',name:'Upiór',level:10,maxHp:500,attack:[60,60],reward:{gold:500,xp:11100,magicDust:10,deadBones:1}},
 {id:'grave-skeleton',name:'Szkielet',level:13,maxHp:700,attack:[50,50],reward:{gold:500,xp:22000,magicDust:20,rareMaterial:5,deadBones:5}},
 {id:'grave-lich',name:'Licz',level:15,maxHp:700,attack:[80,80],reward:{gold:500,xp:50000,magicDust:30,deadBones:5}},
 {id:'grave-knight',name:'Czarny Rycerz',level:18,maxHp:1000,attack:[99,99],reward:{gold:1000,xp:100000,magicDust:50,blackSteel:5}},
 {id:'grave-minotaur',name:'Minotaur',level:20,maxHp:1200,attack:[150,150],reward:{gold:2000,xp:250000,shards:10,axe:1}}
 ].map((b,i)=>({...b,tile:i,atlas:'graveyard',stats:[b.level*2,b.level,b.level,b.level*2]}));
 const NAMES={gold:'Złoto',xp:'EXP',magicDust:'Magiczny pył',rareMaterial:'Rzadki Materiał',deadBones:'Kość truposza',blackSteel:'Czarny kawałek stali',shards:'Odłamki',axe:'Topór Minotaura'};
 function count(h){const ids=h.graveyardDefeated??[];if(!Array.isArray(ids)||ids.length>5||ids.some((id,i)=>id!==BOSSES[i].id))throw Error('Nieprawidłowy postęp Cmentarzyska.');return ids.length;}
 function rewardText(r){return Object.entries(r).map(([k,n])=>`${NAMES[k]}: ${n}`).join(' · ');}
 function award(h,r){let next=window.Progression.award(h,r.xp);for(const key of ['gold','shards','magicDust','rareMaterial','deadBones','blackSteel']){const amount=r[key]??0,base=next[key]??(key==='gold'?25:0);if(!Number.isSafeInteger(base)||base<0||!Number.isSafeInteger(base+amount))throw Error('Nieprawidłowa ilość nagród.');if(amount)next={...next,[key]:base+amount};}
 if(r.axe)next={...next,lootInventory:[...window.HeroSheet.inventory(next),{id:'minotaur-axe',name:'Topór Minotaura',kind:'minotaur-axe',slot:'weapon',requiredLevel:20}]};
 if(window.HeroSheet.bagItems(next).length>25)throw Error('Ekwipunek pełny. Zwolnij miejsce na wszystkie nagrody bossa.');return next;}
 function start(h,index,now=Date.now()){if(!window.GabrielTraining.unlocked(h))throw Error('Najpierw ukończ misje treningowe u Gabriela.');if(window.Progression.level(h)<10)throw Error('Cmentarzysko wymaga poziomu 10.');if(h.activeCombat||h.activeMission)throw Error('Najpierw zakończ obecną walkę lub misję.');if(cooldown(h,now).remaining)throw Error('Kolejna walka w lochach za '+cooldown(h,now).text+'.');if(index!==count(h)||!BOSSES[index])throw Error('Najpierw pokonaj poprzedniego bossa.');const boss=BOSSES[index];award(h,boss.reward);const player=window.BrandCombat.profile(h),power=Math.max(...player.stats)+player.level*2+(player.damageBonus||0);player.attack=[Math.max(1,power-3),power+3];return {...h,activeCombat:{id:crypto.randomUUID(),source:'graveyard',bossIndex:index,cost:0,sceneId:'graveyard',reward:{...boss.reward},battle:window.BrandCombat.createBattle(player,boss,'hero'),nextHitAt:Date.now()+1100}};}
 function resolve(h,id,now=Date.now()){const f=h.activeCombat,index=count(h);if(!f||f.id!==id||f.source!=='graveyard'||!f.battle.winner||f.bossIndex!==index||f.battle.enemy.id!==BOSSES[index]?.id)throw Error('Walka trwa lub została już rozliczona.');const won=f.battle.winner==='hero',reward=won?f.reward:{gold:0,xp:0},next=won?award(h,reward):h;return {...next,activeCombat:null,dungeonNextFightAt:now+COOLDOWN,graveyardDefeated:won?[...(h.graveyardDefeated??[]),BOSSES[index].id]:[...(h.graveyardDefeated??[])],lastGraveyard:{id,won,index,reward,levelsGained:window.Progression.level(next)-window.Progression.level(h)}};}
 function markup(h){const n=count(h),active=h.activeCombat?.source==='graveyard',last=h.lastGraveyard,waiting=cooldown(h).remaining>0;return `<p class="dungeon-cooldown" data-dungeon-cooldown>${waiting?'Kolejna walka w lochach za '+cooldown(h).text:'Walka w lochach dostępna.'}</p>`+ `${last?`<div class="grave-reward" role="status"><strong>${last.won?'Zwycięstwo — '+BOSSES[last.index].name:'Porażka'}</strong><p>${last.won?rewardText(last.reward):(window.BrandCombat.isNecromancer(h)?'Nie otrzymujesz nagrody. Możesz walczyć ponownie bez czekania.':'Nie otrzymujesz nagrody. Kolejna próba po 3 godzinach.')}</p></div>`:''}<p>Pokonani bossowie: ${n} / 5. Następny odblokowuje się po zwycięstwie nad poprzednim.</p>${active?'<button type="button" class="primary" data-resume-graveyard>Wróć do walki</button>':''}<div class="grave-bosses">${BOSSES.map((b,i)=>`<article class="grave-boss ${i>n?'locked':''}"><div class="grave-avatar" style="--boss-x:${i%3*50}%;--boss-y:${Math.floor(i/3)*100}%" role="img" aria-label="${b.name}"></div><h3>${b.name}</h3><p>Poziom ${b.level} · ${b.maxHp} HP · Obrażenia ${b.attack[0]}</p><p>${rewardText(b.reward)}</p><button type="button" class="primary" data-grave-boss="${i}" ${i!==n||h.activeCombat||h.activeMission||waiting?'disabled':''}>${i<n?'Pokonany':i>n?'Zablokowany':'Walcz'}</button></article>`).join('')}</div>${n===5?'<p>Cmentarzysko ukończone. Wszystkie nagrody zostały odebrane.</p>':''}`;}
 window.Graveyard={COOLDOWN,cooldown,BOSSES,count,start,resolve,award,markup};
})();
